// TomNumberFromTerm is Java Gom's TomNumber.fromTerm(trm).
func TomNumberFromTerm(trm aterm.ATerm) TomNumber {
	return TomNumberFromTermConv(trm, aterm.IdConverter{})
}

// TomNumberFromTermConv is Java Gom's TomNumber.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func TomNumberFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) TomNumber {
	converted := conv.Convert(trm)
	var results []TomNumber
	if r, ok := fromTermMatchNumberTomNumber(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermPatternNumberTomNumber(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermListNumberTomNumber(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermIndexNumberTomNumber(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermBeginTomNumber(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermEndTomNumber(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermSaveTomNumber(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermPositionTomNumber(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermAbsVarTomNumber(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermRenamedVarTomNumber(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermNameNumberTomNumber(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a TomNumber", trm), IllegalArgument: true})
	}
	return results[0]
}

// TomNumberFromString is Java Gom's TomNumber.fromString(s).
func TomNumberFromString(s string) TomNumber { return TomNumberFromTerm(aterm.GetInstance().Parse(s)) }

// TomNumberFromStream is Java Gom's TomNumber.fromStream(stream) (an IOException is
// the error).
func TomNumberFromStream(stream io.Reader) (TomNumber, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return TomNumberFromTerm(at), nil
}

