// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new TomName[]{}): a last tail
// that is not a list (of sort TomNameList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcTomNameTomNameList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur TomNameList = t
	for {
		c, ok := cur.(*ConcTomNameTomNameList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcTomNameTomNameList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a concTomName list is not a TomName", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *ConcTomNameTomNameList) ChildCount() int { return len(t.elements()) }

func (t *ConcTomNameTomNameList) ChildAt(i int) any { return t.elements()[i] }

func (t *ConcTomNameTomNameList) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *ConcTomNameTomNameList) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: ConcTomNameFromArray(children).
func (t *ConcTomNameTomNameList) SetChildren(children []any) any {
	args := make([]TomName, len(children))
	for i, c := range children {
		args[i] = c.(TomName)
	}
	return MakeConcTomName(args...)
}

func (t *ConcTomNameTomNameList) String() string {
	var b strings.Builder
	b.WriteString("concTomName(")
	var cur TomNameList = t
	for {
		c, ok := cur.(*ConcTomNameTomNameList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsConcTomName is Java Gom's ConsconcTomName.realMake: the shared cell of head
