func realMakeEmptyConcTomName() TomNameList {
	proto := &ConcTomNameTomNameList{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyconcTomName"), nil)}
	return factory.Build(proto).(*ConcTomNameTomNameList)
}

// RawConcTomName builds the concTomName list holding exactly args, without construction
// hook.
func RawConcTomName(args ...TomName) TomNameList {
	l := realMakeEmptyConcTomName()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsConcTomName(args[i], l)
	}
	return l
}

// EmptyConcTomName is Java Gom's EmptyconcTomName.make(): the empty concTomName list, after the
